import{j as e}from"./vendor-motion-D-QS5Tde.js";import{H as t}from"./index-DTryBJkQ.js";import{N as s,F as i}from"./Footer-KawF-dDP.js";import{P as n,C as a,N as o}from"./NextProject-BUYY37sz.js";import{C as r}from"./CsSection-D4zIf1tb.js";import{C as l}from"./CsThanks-Cx9c-DN_.js";import{B as c}from"./BottomNav-BQIsGLMm.js";import"./vendor-react-P2F7fkol.js";import"./vendor-three-CMud_36L.js";function w(){return e.jsxs(e.Fragment,{children:[e.jsxs(t,{children:[e.jsx("title",{children:"The Omakase · Parth Pawar"}),e.jsx("meta",{name:"description",content:"The Omakase is a 2-player party arcade game where sushi chefs compete to serve customers — a creative technology and game design project."}),e.jsx("meta",{property:"og:type",content:"article"}),e.jsx("meta",{property:"og:title",content:"The Omakase · Parth Pawar"}),e.jsx("meta",{property:"og:description",content:"2-player party arcade game where sushi chefs compete to serve customers."}),e.jsx("meta",{property:"og:image",content:"https://parthpawar.com/Assets/images/the-omakase.jpg"})]}),e.jsx(s,{}),e.jsxs("main",{id:"main-content",className:"project-main",style:{"--project-color":"#C94C4C"},children:[e.jsx(n,{backLink:"/work",categorySlug:"installations",backLabel:"Back to Work",tags:["Creative Technology","Game Design"],title:"The Omakase",subtitle:"2-player party arcade game where sushi chefs compete to serve customers",info:[{label:"Year",value:"2024"},{label:"Role",value:"Creator"}]}),e.jsx("section",{className:"cs-slide reveal",children:e.jsx("div",{style:{padding:"56.25% 0 0 0",position:"relative"},children:e.jsx("iframe",{src:"https://player.vimeo.com/video/996020990?h=&badge=0&autopause=0&player_id=0&app_id=58479",frameBorder:"0",allow:"autoplay; fullscreen; picture-in-picture",allowFullScreen:!0,style:{position:"absolute",top:0,left:0,width:"100%",height:"100%"},title:"The Omakase"})})}),e.jsx(r,{label:"Overview",title:"Serve or Be Served",children:e.jsxs(a,{children:[e.jsx("p",{children:"The Omakase is a 2-player competitive arcade game where two sushi chefs race to serve customers their feast before their opponent does. Built from scratch as a custom arcade cabinet, the game combines physical computing, game design, and fabrication into a single cohesive experience. Each player commands a set of 8 RGB LED buttons that shift color throughout gameplay, requiring fast pattern recognition, sharp reflexes, and a willingness to get a little messy under pressure."}),e.jsx("p",{children:"The project was conceived as a thesis exploration into how physical arcade games can create spontaneous social moments between strangers. It was exhibited at the ITP Spring Show 2024 at NYU and later shown at Wonderville Brooklyn, an indie arcade bar in Bushwick."}),e.jsx("p",{children:e.jsx("a",{href:"https://vill4n3lle.itch.io/the-omakase",target:"_blank",rel:"noopener",children:"Play at vill4n3lle.itch.io/the-omakase →"})})]})}),e.jsx("section",{className:"cs-section reveal",id:"cs-challenge",children:e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"00 — Challenge"}),e.jsx("h3",{className:"cs-section-title",children:"The Design Challenge"}),e.jsxs(a,{children:[e.jsx("p",{children:"The core challenge was deceptively simple: design a physical arcade game that two complete strangers can walk up to, understand immediately, and play competitively in under three minutes. That constraint shaped every decision that followed."}),e.jsx("p",{children:"Most arcade games at exhibitions fail one of two ways. They are either too complex for a first-time player to pick up without instruction, or too shallow to hold attention past the first thirty seconds. The Omakase needed to land in the narrow space between those extremes — instantly readable rules, but enough depth that the second round feels different from the first. The game also had to work in an exhibition context where noise levels are high, attention spans are short, and there is always a line of people waiting for their turn."}),e.jsx("p",{children:"A secondary challenge was designing for physicality. Unlike screen-based games, the cabinet itself had to communicate how to play. Button layout, color feedback, and the spatial relationship between the two players all had to do instructional work that a tutorial screen would normally handle. The game needed to teach itself."})]})]})}),e.jsxs("section",{className:"cs-section reveal",id:"cs-gameplay",children:[e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"01 — Gameplay"}),e.jsx("h3",{className:"cs-section-title",children:"Gameplay"}),e.jsxs(a,{children:[e.jsx("p",{children:"Two players face off as competing sushi chefs, standing side by side at the cabinet. Each player has 8 color-changing buttons mapped to different sushi ingredients — salmon, tuna, shrimp, tamago, and so on. Customer orders appear on the shared screen, and players race to press the correct ingredient sequence before their opponent completes theirs."}),e.jsx("p",{children:"The sushi theme was chosen deliberately. Sushi is universally recognizable, its ingredients are visually distinct, and the concept of an omakase — a chef’s choice tasting menu — gave the game a natural narrative arc. Each round is a “course,” and the escalating difficulty mirrors the progression of a real omakase meal from simple nigiri to elaborate rolls. The theme also made color-coding intuitive: players could map salmon-pink to salmon and wasabi-green to wasabi without any text labels."}),e.jsx("p",{children:"Competitive mode was chosen over cooperative after early playtesting revealed that side-by-side competition created far more energy and social interaction than cooperative play did. When two strangers cooperate, they tend to be polite and reserved. When they compete, they laugh, trash-talk, and lean into the experience. That energy was essential for an exhibition setting where the game needed to draw a crowd."}),e.jsx("p",{children:"Scoring rewarded both speed and accuracy. Each correct ingredient in a sequence earned base points, but completing a full order without mistakes triggered a combo multiplier. Pressing a wrong ingredient broke the combo and added a brief cooldown penalty, discouraging random button-mashing. This created a risk-reward dynamic: rushing was faster but sloppier, while deliberate play was safer but left you vulnerable to a faster opponent. Rounds lasted 90 seconds, long enough for momentum swings but short enough to keep the queue moving."})]})]}),e.jsx("div",{className:"wrap",children:e.jsx("img",{src:"https://freight.cargo.site/w/2000/i/B1899182472545304968837588124182/1.jpg",alt:"The Omakase gameplay",loading:"lazy"})}),e.jsx("div",{className:"wrap",children:e.jsx("img",{src:"https://freight.cargo.site/w/2000/i/T1899182472600645201058716779030/3.jpg",alt:"The Omakase gameplay detail",loading:"lazy"})})]}),e.jsxs("section",{className:"cs-section reveal",id:"cs-fabrication",children:[e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"02 — Fabrication"}),e.jsx("h3",{className:"cs-section-title",children:"Fabrication"}),e.jsxs(a,{children:[e.jsx("p",{children:"The custom arcade cabinet was built with laser-cut birch plywood panels, an Arduino Mega 2560, and 16 individually addressable RGB LED arcade buttons — 8 per player. The cabinet design references classic Japanese candy cab aesthetics with a sloped control panel and a shared upright screen, adapted for a two-player head-to-head layout."}),e.jsx("p",{children:"Laser cutting was chosen over CNC routing or 3D printing for several practical reasons. The plywood panels needed to be large, flat, and precisely interlocking. Laser cutting gave clean finger joints that slotted together without fasteners, making the cabinet easy to assemble and disassemble for transport between exhibition venues. The entire cabinet breaks down into flat panels that fit in the back of a sedan — a critical requirement when you are hauling an arcade machine across Brooklyn on the subway and then in a rideshare."}),e.jsx("p",{children:"The Arduino Mega was selected over an Uno or a Raspberry Pi because the project needed a large number of digital I/O pins. Each RGB button requires four connections — one for the button input and three for the red, green, and blue LED channels. With 16 buttons, that is 64 pins for the LEDs alone, plus 16 for button inputs. The Mega’s 54 digital I/O pins and 16 analog pins handled this comfortably. A multiplexer could have reduced the pin count on a smaller board, but direct wiring kept the latency imperceptible and the code straightforward, which mattered for a game where milliseconds of input lag would feel unfair."}),e.jsx("p",{children:"The RGB LED buttons were the most critical design element for player feedback. Each button glows in the color of its assigned ingredient during active play, making the mapping between screen and controls immediate and physical. When a player presses the wrong button, all their buttons flash red briefly. When they complete an order, the buttons cascade through a celebratory color animation. This meant players could stay focused on the physical controls rather than constantly glancing at the screen — the cabinet itself communicated game state through light."})]})]}),e.jsx("div",{className:"wrap",children:e.jsx("img",{src:"https://freight.cargo.site/w/2000/i/K1899182472619091945132426330646/4.jpg",alt:"The Omakase fabrication",loading:"lazy"})}),e.jsx("div",{className:"wrap",children:e.jsx("img",{src:"https://freight.cargo.site/w/2000/i/O1899182472637538689206135882262/5.jpg",alt:"The Omakase cabinet detail",loading:"lazy"})})]}),e.jsxs("section",{className:"cs-section reveal",id:"cs-exhibition",children:[e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"03 — Exhibition"}),e.jsx("h3",{className:"cs-section-title",children:"Exhibition"}),e.jsxs(a,{children:[e.jsx("p",{children:"The Omakase debuted at the ITP Spring Show 2024 at NYU’s Tisch School of the Arts, a two-day public exhibition that draws over 5,000 visitors. Over the course of the show, more than 200 people played the game, with a consistent line forming throughout both days. The cabinet became one of the busiest installations on the floor, partly because the competitive format naturally created spectators — people would stop to watch a match, then get in line for the next one."}),e.jsx("p",{children:"The reaction was overwhelmingly positive and, more importantly, exactly the kind of social energy the project was designed to generate. Strangers cheered each other on, rematch requests were constant, and several players came back multiple times across both days. One of the most gratifying observations was that players who had never met would leave the cabinet talking to each other — the shared competitive experience broke the social barrier that usually exists between strangers at a crowded exhibition."}),e.jsx("p",{children:"The game was later shown at Wonderville Brooklyn, an indie arcade bar in Bushwick that hosts experimental and independent arcade games. Playing in a bar context versus an academic exhibition was a very different experience. The energy was louder, the competition more intense, and the social dynamics shifted — players were more willing to trash-talk and celebrate dramatically. The game held up well in both contexts, which validated the core design decisions around simplicity and immediacy."}),e.jsx("p",{children:"If I were to revisit the project, I would make two changes. First, I would add a simple high-score leaderboard displayed on the cabinet between matches. During the show, players kept asking what the highest score was, and not having that visible meant losing a layer of motivation and social competition. Second, I would redesign the wiring harness inside the cabinet. It worked, but servicing a loose connection mid-show required partially disassembling the control panel, which cost about twenty minutes of downtime on day one."})]})]}),e.jsx("div",{className:"wrap",children:e.jsx("img",{src:"https://freight.cargo.site/w/2000/i/P1899182472655985433279845433878/6.jpg",alt:"The Omakase at ITP Spring Show",loading:"lazy"})})]}),e.jsx("section",{className:"cs-section reveal",id:"cs-reflections",children:e.jsxs("div",{className:"wrap",children:[e.jsx("p",{className:"cs-section-label",children:"04 — Reflections"}),e.jsx("h3",{className:"cs-section-title",children:"Reflections"}),e.jsxs(a,{children:[e.jsxs("p",{children:[e.jsx("strong",{children:"Physical feedback changes everything."})," The single biggest lesson from this project was how much the RGB LED buttons transformed the play experience. Early prototypes used keyboard input on a laptop, and players constantly lost track of which key mapped to which ingredient. The moment the buttons lit up in their ingredient colors, onboarding time dropped from about 60 seconds of explanation to near-zero. People walked up and started playing. The physicality of the controls — the satisfying click of an arcade button, the color flashing under your fingers — created a feedback loop that no screen-only interface could match."]}),e.jsxs("p",{children:[e.jsx("strong",{children:"Design for the line, not just the player."})," In an exhibition context, the experience of waiting matters almost as much as the experience of playing. The side-by-side competitive layout meant spectators could see both players’ hands and the screen simultaneously, turning every match into a performance. This was not planned — it was a fortunate consequence of the cabinet’s form factor — but it taught me to think about the entire social context of a physical game, not just the two people holding the controls."]}),e.jsxs("p",{children:[e.jsx("strong",{children:"Constraints are generative."})," The 90-second round timer, the 8-button limit per player, the requirement to be transportable — every constraint that felt limiting during design ended up producing a tighter, more focused experience. Without the transport constraint, the cabinet would have been larger and more impressive-looking but impossible to exhibit anywhere outside ITP. Without the button limit, the game would have been more complex but harder to learn. The project reinforced that creative technology work benefits enormously from self-imposed constraints, especially when the goal is public-facing work that needs to be accessible to everyone."]})]})]})}),e.jsx(l,{}),e.jsx(c,{sections:[{id:"cs-challenge",label:"Challenge"},{id:"cs-gameplay",label:"Gameplay"},{id:"cs-fabrication",label:"Fabrication"},{id:"cs-exhibition",label:"Exhibition"},{id:"cs-reflections",label:"Reflections"}]})]}),e.jsx(o,{slug:"moniac-machine",title:"Moniac Machine",image:"/Assets/images/moniac-machine.jpg"}),e.jsx(i,{})]})}export{w as default};
